      's.pages.lead': 'Each page is a 12 × 6 grid of widgets. Pick a page on the left, arrange its widgets on the phone below and set their options. Drag pages to reorder them; the first one is the home page the panel returns to when idle. On the phone, swipe, use the volume keys, or tap a dot to go to its page (or slide along the dots to pick one); tap the current dot or the grid button next to the dots, or long-press an empty part of a page, for an overview of all pages.',
