      's.display.tabletRowsHint': 'A landscape tablet keeps the 12 columns and gets more rows (about 8 to 10, from its screen), so a page holds more widgets; upright, it packs 12 across. Widgets below the top 6 rows show only on a tablet: a phone leaves them out without a sign. Update the PhoneBox app on the tablet first, as an older app squeezes those widgets onto extra rows.',
      's.pages.screenRowsVary': 'The real number of rows comes from the tablet\'s screen, for example 7 at 1280 × 720 or 9 at 1200 × 800.',
      's.shortcuts.lead': 'The keys shown by Shortcut grid and Big button widgets. Click a key to edit it, drag to reorder. The phone only sends the key\'s id; commands never leave this computer.',
      's.rules.lead': 'Let the panel react to what happens on this computer: show the AI page when Claude needs you, the music page when something plays, an "on air" sign during calls. A rule fires when its condition starts; with only while it lasts the phone goes back to where it was (and a pushed value is removed) when the condition ends.',
