      's.cursor.approvalsHint': 'Cursor\'s hook runs before every shell command and MCP tool call of its agent, also the ones it would run by itself. While a phone is connected, each one waits for Allow or Deny there; without a phone, or with no answer, Cursor goes on as usual. With "Also watch Cursor in WSL" on, the hook is installed in the running distros too (projects opened over Remote - WSL run their hooks there).',
