      's.discord.hint': 'Lege unter discord.com/developers/applications eine Anwendung an, füge unter OAuth2 die Weiterleitung http://127.0.0.1 hinzu und kopiere Client-ID und Secret hierher. Discord bittet dich einmal, PhoneBox zu bestätigen. Lehnt es die Anmeldung ab, füge dein Konto unter App Testers der Anwendung hinzu. Schritt für Schritt: docs/DISCORD.md.',
      's.discord.clientId': 'Client-ID',
