      's.discord.allowControlHint': 'Für die /api/discord-Aktionen des Agenten: Stummschalten, Ton aus, Eingabemodus, Verlassen und Beitreten. Aus: sie funktionieren nur, solange ein Discord-Widget mit eingeschalteter Steuerung auf einer aktivierten Seite liegt. An: sie funktionieren auch ohne. In beiden Fällen kann alles sie nutzen, was den Agenten aufrufen kann, nicht nur das Widget: das gekoppelte Telefon (USB oder WLAN) und Programme auf diesem Computer.',
      's.discord.screenShare': 'Discord-Bildschirmübertragungen vom Telefon starten und beenden',
      's.discord.screenShareHint': 'Fragt Discord nach der Erlaubnis, Bildschirmübertragungen zu starten, daher bittet Discord dich noch einmal, PhoneBox zu bestätigen. Solange die Teilen-Ansicht auf dem Telefon offen ist, listet PhoneBox die Apps mit einem Fenster auf diesem Computer (nur Namen). Discord entscheidet, was es direkt teilen kann; für alles andere nutze seine Auswahl am Computer. Braucht auch ein Discord-Widget mit eingeschalteter Steuerung.',
