      's.nav.advanced': 'Erweitert',
      's.pages.lead': 'Jede Seite ist ein 12 × 6 Raster aus Widgets. Wählen Sie links eine Seite, ordnen Sie ihre Widgets unten auf dem Telefon an und legen Sie ihre Optionen fest. Ziehen Sie Seiten, um sie neu zu sortieren; die erste ist die Startseite, zu der das Panel im Leerlauf zurückkehrt. Wischen Sie auf dem Telefon, nutzen Sie die Lautstärketasten oder tippen Sie auf einen Punkt, um zu seiner Seite zu gehen (oder fahren Sie über die Punkte, um eine auszuwählen); tippen Sie auf den aktuellen Punkt oder die Rastertaste neben den Punkten oder halten Sie eine leere Stelle einer Seite gedrückt, um eine Übersicht aller Seiten zu sehen.',
