      's.pages.screen.wide': 'Breites Tablet',
      's.pages.screenHint': 'Eine Telefonseite ist 12 × 6. Ein Tablet behält die 12 Spalten und fügt Zeilen hinzu, sodass die Seite mehr Widgets aufnimmt. Widgets unterhalb der oberen 6 Zeilen bleiben auf dem Tablet; ein Telefon zeigt die oberen 6.',
