      's.lhm.setup': "Für CPU-Temperatur, CPU-Leistung und zusätzliche GPU-Messwerte unter Windows Options › Remote Web Server › Run auf Port 8085 aktivieren.",
      's.pages.screenHidden': '{n} Widgets liegen auf Zeilen, die dieser Bildschirm nicht zeigt.',
      's.display.tabletRows': 'Mehr Zeilen auf einem Tablet',
      's.display.tabletRowsHint': 'Ein Tablet im Querformat behält die 12 Spalten und bekommt mehr Zeilen (je nach Bildschirm etwa 8 bis 10), sodass eine Seite mehr Widgets aufnimmt; hochkant ordnet es 12 nebeneinander an. Widgets unterhalb der oberen 6 Zeilen erscheinen nur auf einem Tablet: Ein Telefon lässt sie ohne Hinweis weg. Aktualisieren Sie zuerst die PhoneBox-App auf dem Tablet, denn eine ältere App quetscht diese Widgets in zusätzliche Zeilen.',
      's.pages.screenRowsVary': 'Die tatsächliche Zeilenzahl hängt vom Bildschirm des Tablets ab, zum Beispiel 7 bei 1280 × 720 oder 9 bei 1200 × 800.',
      's.shortcuts.lead': 'Die Tasten, die die Widgets „Shortcut grid" und „Big button" anzeigen. Klicken Sie eine Taste zum Bearbeiten, ziehen Sie zum Umsortieren. Das Telefon sendet nur die Kennung der Taste; Befehle verlassen diesen Computer nie.',
      's.rules.lead': 'Lassen Sie das Panel auf Geschehnisse auf diesem Computer reagieren: zeigen Sie die AI-Seite, wenn Claude Sie braucht, die Musikseite, wenn etwas spielt, ein „On Air"-Zeichen während Anrufen. Eine Regel wird ausgelöst, wenn ihre Bedingung beginnt; mit „nur solange sie gilt" kehrt das Telefon zu seinem vorherigen Zustand zurück (und ein gesendeter Wert wird entfernt), wenn die Bedingung endet.',
      's.rules.add': 'Regel hinzufügen',
