      's.cursor.approvalsHint': 'Der Hook von Cursor läuft vor jedem Shell-Befehl und jedem MCP-Werkzeugaufruf seines Agenten, auch vor denen, die er von selbst ausführen würde. Solange ein Telefon verbunden ist, wartet jeder dort auf Erlauben oder Ablehnen; ohne Telefon oder ohne Antwort macht Cursor wie gewohnt weiter. Mit „Cursor auch in WSL beobachten“ wird der Hook auch in den laufenden Distributionen installiert (mit Remote - WSL geöffnete Projekte führen ihre Hooks dort aus).',
      's.claude.watchWsl': 'Claude Code auch in WSL beobachten: seine Sitzungen und seine Anmeldung für das Kontingent, wenn Windows keine hat (gestoppte Distributionen werden dafür nie gestartet)',
      's.claude.extraDirs': 'Weitere Claude-Code-Konten für Kontingent, Sitzungen und Berechtigungsabfragen: eine Bezeichnung und der als CLAUDE_CONFIG_DIR verwendete Ordner. Nur die Bezeichnung gelangt aufs Telefon. Die Bezeichnung ist Teil der Karten-ID: Umbenennen ändert die ID, also das Konto in Widgets, die darauf eingestellt sind, neu wählen.',
