      's.discord.hint': 'Créez une application sur discord.com/developers/applications, ajoutez la redirection http://127.0.0.1 sous OAuth2 et copiez ici son ID client et son secret. Discord vous demande d\'approuver PhoneBox une fois. S\'il refuse la connexion, ajoutez votre compte dans App Testers de l\'application. Pas à pas : docs/DISCORD.md.',
      's.discord.clientId': 'ID client',
