      's.discord.allowControl': 'Permettre aux raccourcis et aux widgets personnalisés de contrôler Discord, sans widget Discord',
      's.discord.allowControlHint': 'Pour les actions /api/discord de l\'agent : couper le micro, couper le son, mode d\'entrée, quitter et rejoindre. Désactivé : elles ne marchent que si un widget Discord dont le contrôle est activé se trouve sur une page activée. Activé : elles marchent sans widget. Dans les deux cas, tout ce qui peut appeler l\'agent peut les utiliser, pas seulement le widget : le téléphone appairé (USB ou Wi-Fi) et les programmes de cet ordinateur.',
      's.discord.screenShare': 'Démarrer et arrêter les partages d\'écran Discord depuis le téléphone',
      's.discord.screenShareHint': 'Demande à Discord l\'autorisation de démarrer des partages d\'écran : Discord vous demande donc d\'autoriser PhoneBox une fois de plus. Tant que la vue de partage est ouverte sur le téléphone, PhoneBox liste les applis qui ont une fenêtre sur cet ordinateur (noms seulement). Discord décide de ce qu\'il peut partager directement ; pour le reste, utilisez son sélecteur sur l\'ordinateur. Nécessite aussi un widget Discord dont le contrôle est activé.',
