      's.nav.advanced': 'Avancé',
      's.pages.lead': 'Chaque page est une grille 12 × 6 de widgets. Choisissez une page à gauche, disposez ses widgets sur le téléphone ci-dessous et réglez leurs options. Faites glisser les pages pour les réordonner ; la première est la page d\'accueil vers laquelle le panneau revient au repos. Sur le téléphone, balayez, utilisez les touches de volume ou touchez un point pour aller à sa page (ou glissez le long des points pour en choisir une) ; touchez le point actuel ou le bouton grille à côté des points, ou maintenez un endroit vide d\'une page, pour avoir une vue de toutes les pages.',
      's.pages.layout': 'Disposition',
      's.pages.livePreview': 'Aperçu en direct',
      's.pages.screen.phone': 'Téléphone',
      's.pages.screen.tablet': 'Tablette',
      's.pages.screen.wide': 'Tablette large',
      's.pages.screenHint': 'Une page de téléphone fait 12 × 6. Une tablette garde les 12 colonnes et ajoute des lignes, donc la page contient plus de widgets. Les widgets sous les 6 premières lignes restent sur la tablette ; un téléphone affiche les 6 premières.',
      's.lhm.checking': "Vérification de la source des capteurs…",
      's.lhm.connected': "Source des capteurs connectée",
      's.lhm.unavailable': "Source des capteurs indisponible",
      's.lhm.setup': "Pour la température et la puissance du processeur et les mesures GPU supplémentaires sous Windows, activez Options › Remote Web Server › Run sur le port 8085.",
      's.pages.screenHidden': '{n} widgets sont sur des lignes que cet écran n\'affiche pas.',
      's.display.tabletRows': 'Plus de lignes sur une tablette',
      's.display.tabletRowsHint': 'Une tablette en paysage garde les 12 colonnes et reçoit plus de lignes (environ 8 à 10, selon son écran), donc une page contient plus de widgets ; à la verticale, elle en aligne 12. Les widgets sous les 6 premières lignes ne s\'affichent que sur une tablette : un téléphone les omet sans le signaler. Mettez d\'abord à jour l\'application PhoneBox sur la tablette : une ancienne version entasse ces widgets sur des lignes en plus.',
      's.pages.screenRowsVary': 'Le nombre réel de lignes dépend de l\'écran de la tablette, par exemple 7 en 1280 × 720 ou 9 en 1200 × 800.',
      's.shortcuts.lead': 'Les touches affichées par les widgets « Shortcut grid » et « Big button ». Cliquez sur une touche pour la modifier, faites-la glisser pour la réordonner. Le téléphone n\'envoie que l\'identifiant de la touche ; les commandes ne quittent jamais cet ordinateur.',
      's.rules.lead': 'Laissez le panneau réagir à ce qui se passe sur cet ordinateur : affichez la page AI quand Claude a besoin de vous, la page musique quand quelque chose joue, un panneau « à l\'antenne » pendant les appels. Une règle se déclenche quand sa condition commence ; avec « seulement tant qu\'elle dure », le téléphone revient là où il était (et une valeur poussée est retirée) quand la condition se termine.',
