      's.discord.hint': 'Crea una aplicación en discord.com/developers/applications, añade la redirección http://127.0.0.1 en OAuth2 y copia aquí su ID de cliente y su secreto. Discord te pide aprobar PhoneBox una vez. Si rechaza el inicio de sesión, añade tu cuenta en App Testers de la aplicación. Paso a paso: docs/DISCORD.md.',
