      's.discord.allowControlHint': 'Para las acciones /api/discord del agente: silenciar, ensordecer, modo de entrada, salir y unirse. Desactivado: solo funcionan mientras haya un widget de Discord con el control activado en una página habilitada. Activado: funcionan sin él. En ambos casos puede usarlas todo lo que pueda llamar al agente, no solo el widget: el teléfono vinculado (USB o Wi-Fi) y los programas de este equipo.',
