      's.discord.screenShareHint': 'Pide a Discord permiso para iniciar transmisiones de pantalla, así que Discord te pide aprobar PhoneBox una vez más. Mientras la vista de compartir está abierta en el teléfono, PhoneBox lista las apps con una ventana en este equipo (solo nombres). Discord decide qué puede compartir directamente; para lo demás usa su selector en el equipo. También requiere un widget de Discord con el control activado.',
