      's.nav.general': 'General',
      's.nav.advanced': 'Avanzado',
      's.pages.lead': 'Cada página es una cuadrícula de 12 × 6 widgets. Elige una página a la izquierda, organiza sus widgets en el teléfono de abajo y ajusta sus opciones. Arrastra las páginas para reordenarlas; la primera es la página de inicio a la que vuelve el panel en reposo. En el teléfono, desliza, usa los botones de volumen o toca un punto para ir a su página (o desliza el dedo sobre los puntos para elegir una); toca el punto actual o el botón de cuadrícula junto a los puntos, o mantén pulsado un espacio vacío de una página, para ver todas las páginas.',
      's.pages.layout': 'Diseño',
      's.pages.livePreview': 'Vista previa',
      's.pages.screen.phone': 'Teléfono',
      's.pages.screen.tablet': 'Tableta',
      's.pages.screen.wide': 'Tableta ancha',
      's.pages.screenHint': 'Una página de teléfono es de 12 × 6. Una tableta mantiene las 12 columnas y añade filas, así que la página admite más widgets. Los widgets debajo de las 6 primeras filas se quedan en la tableta; un teléfono muestra las 6 primeras.',
      's.lhm.checking': "Comprobando el origen de los sensores…",
      's.lhm.connected': "Origen de los sensores conectado",
      's.lhm.unavailable': "Origen de los sensores no disponible",
      's.lhm.setup': "Para la temperatura y la potencia de la CPU y las lecturas adicionales de la GPU en Windows, activa Options › Remote Web Server › Run en el puerto 8085.",
      's.pages.screenHidden': '{n} widgets están en filas que esta pantalla no muestra.',
      's.display.tabletRows': 'Más filas en una tableta',
      's.display.tabletRowsHint': 'Una tableta en horizontal mantiene las 12 columnas y recibe más filas (unas 8 a 10, según su pantalla), así que una página admite más widgets; en vertical, coloca 12 en fila. Los widgets debajo de las 6 primeras filas solo se ven en una tableta: un teléfono los omite sin avisar. Actualiza primero la app PhoneBox de la tableta, porque una versión antigua amontona esos widgets en filas extra.',
      's.pages.screenRowsVary': 'El número real de filas depende de la pantalla de la tableta, por ejemplo 7 a 1280 × 720 o 9 a 1200 × 800.',
      's.shortcuts.lead': 'Las teclas que muestran los widgets «Shortcut grid» y «Big button». Haz clic en una tecla para editarla, arrástrala para reordenar. El teléfono solo envía el id de la tecla; los comandos nunca salen de este ordenador.',
      's.rules.lead': 'Deja que el panel reaccione a lo que pasa en este ordenador: muestra la página de AI cuando Claude te necesita, la página de música cuando algo suena, un cartel de «en el aire» durante las llamadas. Una regla se activa cuando empieza su condición; con «solo mientras dure» el teléfono vuelve a donde estaba (y un valor enviado se retira) cuando la condición termina.',
