      's.cursor.approvalsHint': 'El hook de Cursor se ejecuta antes de cada comando de terminal y cada llamada a herramienta MCP de su agente, también los que ejecutaría por sí solo. Mientras haya un teléfono conectado, cada uno espera allí Permitir o Denegar; sin teléfono, o sin respuesta, Cursor sigue como siempre. Con «Vigilar también Cursor en WSL» activado, el hook también se instala en las distribuciones en ejecución (los proyectos abiertos con Remote - WSL ejecutan sus hooks allí).',
      's.claude.watchWsl': 'Vigilar también Claude Code en WSL: sus sesiones y su inicio de sesión para la cuota cuando Windows no tiene uno (nunca se inicia una distribución detenida para esto)',
      's.claude.extraDirs': 'Otras cuentas de Claude Code para la cuota, las sesiones y las solicitudes de permiso: una etiqueta y la carpeta usada como CLAUDE_CONFIG_DIR. Solo la etiqueta llega al teléfono. La etiqueta forma parte del id de la tarjeta: cambiarla cambia el id, así que elige de nuevo la cuenta en los widgets que la usan.',
