      's.pages.lead': 'Ogni pagina è una griglia 12 × 6 di widget. Scegli una pagina a sinistra, disponi i suoi widget sul telefono qui sotto e imposta le loro opzioni. Trascina le pagine per riordinarle; la prima è la home a cui il pannello torna da inattivo. Sul telefono scorri, usa i tasti del volume o tocca un punto per andare alla sua pagina (o fai scorrere il dito sui punti per sceglierne una); tocca il punto attuale o il pulsante a griglia accanto ai punti, o tieni premuto un punto vuoto di una pagina, per vedere tutte le pagine.',
