      's.pages.screenHint': 'Una pagina del telefono è 12 × 6. Un tablet mantiene le 12 colonne e aggiunge righe, così la pagina contiene più widget. I widget sotto le prime 6 righe restano sul tablet; un telefono mostra le prime 6.',
      's.lhm.checking': "Controllo della sorgente dei sensori…",
