      's.lhm.unavailable': "Sorgente dei sensori non disponibile",
      's.lhm.setup': "Per la temperatura e la potenza della CPU e le letture aggiuntive della GPU in Windows, attiva Options › Remote Web Server › Run sulla porta 8085.",
      's.pages.screenHidden': '{n} widget si trovano su righe che questo schermo non mostra.',
      's.display.tabletRows': 'Più righe su un tablet',
      's.display.tabletRowsHint': 'Un tablet in orizzontale mantiene le 12 colonne e riceve più righe (circa da 8 a 10, in base allo schermo), così una pagina contiene più widget; in verticale ne affianca 12. I widget sotto le prime 6 righe compaiono solo su un tablet: un telefono li omette senza avvisare. Aggiorna prima l\'app PhoneBox sul tablet: una versione precedente ammassa quei widget su righe in più.',
      's.pages.screenRowsVary': 'Il numero reale di righe dipende dallo schermo del tablet, per esempio 7 a 1280 × 720 o 9 a 1200 × 800.',
      's.shortcuts.lead': 'I tasti mostrati dai widget «Shortcut grid» e «Big button». Fai clic su un tasto per modificarlo, trascinalo per riordinare. Il telefono invia solo l\'id del tasto; i comandi non escono mai da questo computer.',
      's.rules.lead': 'Lascia che il pannello reagisca a ciò che accade su questo computer: mostra la pagina AI quando Claude ha bisogno di te, la pagina musica quando qualcosa è in riproduzione, un cartello «on air» durante le chiamate. Una regola scatta quando la sua condizione inizia; con «solo finché dura» il telefono torna dov\'era (e un valore inviato viene rimosso) quando la condizione finisce.',
