      's.discord.screenShare': 'Iniciar e parar partilhas de ecrã do Discord a partir do telemóvel',
      's.discord.screenShareHint': 'Pede ao Discord permissão para iniciar partilhas de ecrã, por isso o Discord pede-lhe para aprovar o PhoneBox mais uma vez. Enquanto a vista de partilha está aberta no telemóvel, o PhoneBox lista as apps com uma janela neste computador (só os nomes). O Discord decide o que pode partilhar diretamente; para o resto use o seletor dele no computador. Também precisa de um widget Discord com o controlo ligado.',
