      's.pages.lead': 'Cada página é uma grelha de 12 × 6 widgets. Escolha uma página à esquerda, organize os seus widgets no telemóvel abaixo e defina as suas opções. Arraste as páginas para as reordenar; a primeira é a página inicial para onde o painel volta quando está parado. No telemóvel, deslize, use as teclas de volume ou toque num ponto para ir para a sua página (ou deslize o dedo pelos pontos para escolher uma); toque no ponto atual ou no botão de grelha ao lado dos pontos, ou mantenha premido um espaço vazio de uma página, para ver todas as páginas.',
