      's.pages.screen.wide': 'Tablet largo',
      's.pages.screenHint': 'Uma página de telemóvel tem 12 × 6. Um tablet mantém as 12 colunas e acrescenta linhas, por isso a página leva mais widgets. Os widgets abaixo das 6 primeiras linhas ficam no tablet; um telemóvel mostra as 6 primeiras.',
      's.lhm.checking': "A verificar a origem dos sensores…",
      's.lhm.connected': "Origem dos sensores ligada",
      's.lhm.unavailable': "Origem dos sensores indisponível",
      's.lhm.setup': "Para a temperatura e potência do CPU e as leituras adicionais da GPU no Windows, ative Options › Remote Web Server › Run na porta 8085.",
      's.pages.screenHidden': '{n} widgets estão em linhas que este ecrã não mostra.',
      's.display.tabletRows': 'Mais linhas num tablet',
      's.display.tabletRowsHint': 'Um tablet na horizontal mantém as 12 colunas e ganha mais linhas (cerca de 8 a 10, conforme o ecrã), por isso uma página leva mais widgets; na vertical, alinha 12 lado a lado. Os widgets abaixo das 6 primeiras linhas só aparecem num tablet: um telemóvel omite-os sem aviso. Atualize primeiro a app PhoneBox no tablet, pois uma versão antiga aperta esses widgets em linhas extra.',
      's.pages.screenRowsVary': 'O número real de linhas depende do ecrã do tablet, por exemplo 7 em 1280 × 720 ou 9 em 1200 × 800.',
      's.shortcuts.lead': 'As teclas mostradas pelos widgets «Shortcut grid» e «Big button». Clique numa tecla para a editar, arraste para reordenar. O telemóvel envia apenas o id da tecla; os comandos nunca saem deste computador.',
      's.rules.lead': 'Deixe o painel reagir ao que acontece neste computador: mostre a página de AI quando o Claude precisar de si, a página de música quando algo tocar, um aviso «no ar» durante chamadas. Uma regra dispara quando a sua condição começa; com «só enquanto durar» o telemóvel volta aonde estava (e um valor enviado é removido) quando a condição termina.',
