      's.cursor.approvalsHint': 'O hook do Cursor é executado antes de cada comando de terminal e de cada chamada de ferramenta MCP do agente, incluindo os que executaria sozinho. Enquanto houver um telemóvel ligado, cada um aguarda aí Permitir ou Recusar; sem telemóvel, ou sem resposta, o Cursor continua como habitualmente. Com «Acompanhar também o Cursor no WSL» ativo, o hook também é instalado nas distribuições em execução (os projetos abertos com Remote - WSL executam aí os seus hooks).',
