      's.discord.title': 'Discord',
      's.discord.enable': 'Conectar ao app Discord neste PC (para o widget Discord)',
      's.discord.hint': 'Crie um aplicativo em discord.com/developers/applications, adicione o redirecionamento http://127.0.0.1 em OAuth2 e copie para cá o Client ID e o Client Secret. O Discord vai pedir para você aprovar o PhoneBox uma vez. Se o login for recusado, adicione sua conta em App Testers do aplicativo. Passo a passo: docs/DISCORD.md.',
