      's.discord.allowControl': 'Permitir que atalhos e widgets próprios controlem o Discord, sem um widget do Discord',
      's.discord.allowControlHint': 'Para as ações /api/discord do agente: silenciar, ensurdecer, modo de entrada, sair e entrar. Desligado: só funcionam enquanto houver um widget do Discord com o controle ligado em uma página ativada. Ligado: funcionam sem ele. Nos dois casos, tudo o que consegue chamar o agente pode usá-las, não só o widget: o celular pareado (USB ou Wi-Fi) e os programas deste computador.',
      's.discord.screenShare': 'Iniciar e parar compartilhamentos de tela do Discord pelo celular',
      's.discord.screenShareHint': 'Pede ao Discord permissão para iniciar compartilhamentos de tela, então o Discord pede que você aprove o PhoneBox mais uma vez. Enquanto a visão de compartilhar está aberta no celular, o PhoneBox lista os apps com uma janela neste computador (só os nomes). O Discord decide o que consegue compartilhar diretamente; para o resto use o seletor dele no computador. Também precisa de um widget do Discord com o controle ligado.',
