      's.nav.advanced': 'Avançado',
      's.pages.lead': 'Cada página é uma grade de 12 × 6 widgets. Escolha uma página à esquerda, organize seus widgets no telefone abaixo e defina suas opções. Arraste as páginas para reordená-las; a primeira é a página inicial para onde o painel volta quando está parado. No telefone, deslize, use as teclas de volume ou toque em um ponto para ir para a página dele (ou deslize o dedo pelos pontos para escolher uma); toque no ponto atual ou no botão de grade ao lado dos pontos, ou mantenha pressionado um espaço vazio de uma página, para ver todas as páginas.',
      's.pages.layout': 'Disposição',
