      's.pages.screen.wide': 'Tablet largo',
      's.pages.screenHint': 'Uma página de telefone tem 12 × 6. O tablet mantém as 12 colunas e acrescenta linhas, então a página comporta mais widgets. Widgets abaixo das 6 primeiras linhas ficam no tablet; o telefone mostra as 6 primeiras.',
      's.lhm.checking': "Verificando a fonte dos sensores…",
      's.lhm.connected': "Fonte dos sensores conectada",
      's.lhm.unavailable': "Fonte dos sensores indisponível",
      's.lhm.setup': "Para a temperatura e a potência da CPU e as leituras adicionais da GPU no Windows, ative Options › Remote Web Server › Run na porta 8085.",
      's.pages.screenHidden': '{n} widgets estão em linhas que esta tela não mostra.',
      's.display.tabletRows': 'Mais linhas no tablet',
      's.display.tabletRowsHint': 'Um tablet na horizontal mantém as 12 colunas e ganha mais linhas (cerca de 8 a 10, conforme a tela), então uma página comporta mais widgets; na vertical, ele organiza 12 lado a lado. Widgets abaixo das 6 primeiras linhas só aparecem no tablet: o telefone os omite sem aviso. Atualize primeiro o app PhoneBox no tablet, pois uma versão antiga espreme esses widgets em linhas extras.',
      's.pages.screenRowsVary': 'O número real de linhas depende da tela do tablet, por exemplo 7 em 1280 × 720 ou 9 em 1200 × 800.',
      's.shortcuts.lead': 'As teclas mostradas pelos widgets “Shortcut grid” e “Big button”. Clique em uma tecla para editá-la, arraste para reordenar. O telefone envia apenas o id da tecla; os comandos nunca saem deste computador.',
      's.rules.lead': 'Deixe o painel reagir ao que acontece neste computador: mostre a página de IA quando o Claude precisar de você, a página de música quando algo tocar, um aviso “no ar” durante chamadas. Uma regra dispara quando sua condição começa; com “apenas enquanto durar” o telefone volta para onde estava (e um valor enviado é removido) quando a condição termina.',
