      's.cal.hint': 'Para o widget <b>Agenda</b> e regras de calendário. Cole um endereço iCalendar (ICS): Google Agenda › Configurações › sua agenda › <i>Endereço secreto no formato iCal</i>; Outlook › Configurações › Calendário › Calendários compartilhados › <i>Publicar um calendário</i> (link ICS); iCloud › compartilhar como calendário público (<code>webcal://</code> funciona). Os endereços ficam só neste computador.',
      's.ha.tokenHint': 'Para o widget <b>Home Assistant</b>. Crie um token em Home Assistant › seu perfil › Segurança › <i>Long-lived access tokens</i>. O token fica só neste computador; o telefone só vê as entidades listadas pelos widgets. (O Home Assistant também pode enviar valores e notificações ao painel, veja Webhooks.)',
      's.obs.enable': 'Conectar ao OBS (para o widget <b>OBS</b>, o widget No ar e regras)',
      's.obs.hint': 'No OBS: Tools › WebSocket Server Settings › <i>Enable WebSocket server</i>; copie a senha em <i>Show Connect Info</i>.',
      's.battery.leadTail': 'na fonte: uma <b>tomada inteligente no Home Assistant</b> (o telefone no próprio carregador), ou dois <b>atalhos</b>, por exemplo <code>uhubctl</code> para um hub USB com portas que podem ser ligadas e desligadas. Sem energia USB, o painel continua funcionando via Wi-Fi.',
      's.claude.hint': 'Quando o Claude Code pede permissão (executar um comando, editar um arquivo…), o telefone mostra o pedido com <b>Permitir</b> e <b>Negar</b>. Se o telefone não estiver conectado ou ninguém responder a tempo, o Claude Code pergunta no terminal como de costume. Isso precisa de um pequeno hook em <code>~/.claude/settings.json</code>; o PhoneBox o adiciona para você (um backup é mantido ao lado do arquivo).',
      's.wifi.lead': 'Pareie um telefone conectando-o uma vez via USB depois de ativar isto (e reiniciar), ou sem cabo: <b>Parear um telefone via Wi-Fi</b> mostra um QR code para escanear com a câmera do telefone. O telefone então se comunica via HTTPS com este PC, confia apenas no certificado deste PC e precisa apresentar uma chave secreta. O telefone e este PC precisam estar na mesma rede &mdash; ou ambos no <a href="https://tailscale.com" target="_blank" rel="noopener">Tailscale</a>, que também funciona de outro lugar ou entre redes Wi-Fi separadas. O Firewall do Windows pergunta uma vez &mdash; permita (marque também o tipo de rede que o Tailscale usa).',
      's.upd.checksBefore': 'Verifica',
      's.upd.checksAfter': 'no GitHub a cada 6 horas. O aplicativo do telefone é instalado via USB sem pedir confirmação no telefone; o agente substitui seus próprios arquivos e reinicia.',
