      's.battery.leadHead': 'Um telefone que fica conectado o tempo todo desgasta a bateria. O PhoneBox pode mantê-la entre dois',
      's.battery.leadMid': 'níveis ligando e desligando a energia do telefone. Telefones não conseguem parar de carregar sozinhos sem root, então a energia é cortada',
      's.wh.payloadHintFull': 'Os payloads JSON podem conter <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / warn / error), <code>progress</code> (0&ndash;1 ou 0&ndash;100), <code>items</code> (uma lista) e <code>ttl</code> (segundos). Texto simples ou um número também funciona. Notificações recebem <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (acende a tela noturna) e <code>page</code> (muda para ela).',
