      's.pages.lead': 'Elke pagina is een raster van 12 × 6 widgets. Kies links een pagina, rangschik haar widgets op de telefoon hieronder en stel hun opties in. Sleep pagina\'s om ze te herschikken; de eerste is de homepagina waarheen het paneel bij inactiviteit terugkeert. Veeg op de telefoon, gebruik de volumetoetsen of tik op een puntje om naar die pagina te gaan (of schuif over de puntjes om er een te kiezen); tik op het huidige puntje of de rasterknop naast de puntjes, of houd een lege plek op een pagina ingedrukt, voor een overzicht van alle pagina\'s.',
