      's.pages.lead': 'Każda strona to siatka 12 × 6 widżetów. Wybierz stronę po lewej, rozmieść jej widżety na telefonie poniżej i ustaw ich opcje. Przeciągnij strony, by zmienić ich kolejność; pierwsza jest stroną główną, do której panel wraca po bezczynności. Na telefonie przesuń palcem, użyj klawiszy głośności lub dotknij kropki, by przejść do jej strony (albo przesuń palcem po kropkach, by wybrać stronę); dotknij bieżącej kropki lub przycisku siatki obok kropek albo przytrzymaj puste miejsce na stronie, by zobaczyć wszystkie strony.',
