      's.rules.lead': 'Pozwól panelowi reagować na to, co dzieje się na tym komputerze: pokazuj stronę AI, gdy Claude cię potrzebuje, stronę muzyki, gdy coś gra, znak „na antenie" podczas rozmów. Reguła uruchamia się, gdy zaczyna jej warunek; z „tylko póki trwa" telefon wraca tam, gdzie był (a wysłana wartość jest usuwana), gdy warunek się kończy.',
