      's.nav.advanced': 'Расширенные',
      's.pages.lead': 'Каждая страница — сетка виджетов 12 × 6. Выберите страницу слева, разместите её виджеты на телефоне ниже и задайте их параметры. Перетащите страницы, чтобы изменить порядок; первая — домашняя, к ней панель возвращается после простоя. На телефоне смахивайте, используйте клавиши громкости или коснитесь точки, чтобы перейти на её страницу (либо проведите пальцем по точкам, чтобы выбрать страницу); коснитесь текущей точки или кнопки-сетки рядом с точками либо удерживайте пустое место на странице, чтобы увидеть все страницы.',
