      's.pages.screenHint': 'Страница телефона — 12 × 6. Планшет сохраняет 12 столбцов и добавляет строки, поэтому на странице помещается больше виджетов. Виджеты ниже первых 6 строк остаются на планшете; телефон показывает первые 6.',
      's.lhm.checking': "Проверка источника данных датчиков…",
