      's.lhm.setup': "Для температуры и мощности процессора и дополнительных показателей GPU в Windows включите Options › Remote Web Server › Run на порту 8085.",
      's.pages.screenHidden': 'Виджетов в строках, которые этот экран не показывает: {n}.',
      's.display.tabletRows': 'Больше строк на планшете',
      's.display.tabletRowsHint': 'Планшет в альбомной ориентации сохраняет 12 столбцов и получает больше строк (примерно 8–10, в зависимости от экрана), поэтому на странице помещается больше виджетов; в портретной он ставит 12 в ряд. Виджеты ниже первых 6 строк видны только на планшете: телефон пропускает их без предупреждения. Сначала обновите приложение PhoneBox на планшете: старая версия втиснет эти виджеты в лишние строки.',
      's.pages.screenRowsVary': 'Реальное число строк зависит от экрана планшета, например 7 при 1280 × 720 или 9 при 1200 × 800.',
      's.shortcuts.lead': 'Клавиши, которые показывают виджеты «Shortcut grid» и «Big button». Щёлкните клавишу для правки, перетащите для изменения порядка. Телефон передаёт только id клавиши; команды никогда не покидают этот компьютер.',
      's.rules.lead': 'Пусть панель реагирует на происходящее на этом компьютере: показывает страницу AI, когда Claude нужен, страницу музыки, когда что-то играет, табличку «в эфире» во время звонков. Правило срабатывает, когда начинается его условие; с «только пока действует» телефон возвращается туда, где был (а отправленное значение удаляется), когда условие заканчивается.',
