      's.discord.title': 'Discord',
      's.discord.enable': 'Σύνδεση με την εφαρμογή Discord σε αυτόν τον υπολογιστή (για το widget Discord)',
      's.discord.hint': 'Δημιούργησε μια εφαρμογή στο discord.com/developers/applications, πρόσθεσε την ανακατεύθυνση http://127.0.0.1 στην ενότητα OAuth2 και αντίγραψε εδώ το client ID και το secret της. Το Discord θα σου ζητήσει μία φορά να εγκρίνεις το PhoneBox. Αν αρνηθεί τη σύνδεση, πρόσθεσε τον λογαριασμό σου στους App Testers της εφαρμογής. Βήμα προς βήμα: docs/DISCORD.md.',
