      's.discord.allowControlHint': 'Για τις ενέργειες /api/discord του agent: σίγαση, απενεργοποίηση ήχου, λειτουργία εισόδου, αποχώρηση και συμμετοχή. Ανενεργό: λειτουργούν μόνο όσο υπάρχει widget Discord με ενεργό έλεγχο σε ενεργοποιημένη σελίδα. Ενεργό: λειτουργούν και χωρίς αυτό. Και στις δύο περιπτώσεις μπορεί να τις χρησιμοποιήσει ό,τι μπορεί να καλέσει τον agent, όχι μόνο το widget: το συζευγμένο τηλέφωνο (USB ή Wi-Fi) και τα προγράμματα σε αυτόν τον υπολογιστή.',
      's.discord.screenShare': 'Έναρξη και διακοπή κοινής χρήσης οθόνης Discord από το τηλέφωνο',
      's.discord.screenShareHint': 'Ζητά από το Discord άδεια να ξεκινά κοινή χρήση οθόνης, οπότε το Discord σου ζητά να εγκρίνεις ξανά το PhoneBox. Όσο η προβολή κοινής χρήσης είναι ανοιχτή στο τηλέφωνο, το PhoneBox δείχνει τις εφαρμογές με παράθυρο σε αυτόν τον υπολογιστή (μόνο ονόματα). Το Discord αποφασίζει τι μπορεί να μοιραστεί απευθείας· για τα υπόλοιπα χρησιμοποίησε την επιλογή του στον υπολογιστή. Χρειάζεται και ένα widget Discord με ενεργό τον έλεγχο.',
