      's.nav.general': 'Γενικά',
      's.nav.advanced': 'Για προχωρημένους',
      's.pages.lead': 'Κάθε σελίδα είναι ένα πλέγμα 12 × 6 για widget. Διάλεξε μια σελίδα αριστερά, τακτοποίησε τα widget της στο τηλέφωνο παρακάτω και όρισε τις επιλογές τους. Σύρε τις σελίδες για να αλλάξεις τη σειρά τους· η πρώτη είναι η αρχική σελίδα, στην οποία επιστρέφει ο πίνακας όταν δεν τον αγγίζει κανείς. Στο τηλέφωνο, σύρε το δάχτυλο, χρησιμοποίησε τα πλήκτρα έντασης ή πάτα μια τελεία για να πας στη σελίδα της (ή σύρε το δάχτυλο πάνω στις τελείες για να διαλέξεις μία)· πάτα την τρέχουσα τελεία ή το κουμπί πλέγματος δίπλα στις τελείες, ή κράτα πατημένο ένα κενό σημείο μιας σελίδας, για να δεις όλες τις σελίδες μαζί.',
      's.pages.layout': 'Διάταξη',
      's.pages.livePreview': 'Ζωντανή προεπισκόπηση',
      's.pages.screen.phone': 'Τηλέφωνο',
      's.pages.screen.tablet': 'Tablet',
      's.pages.screen.wide': 'Φαρδύ tablet',
      's.pages.screenHint': 'Μια σελίδα τηλεφώνου είναι 12 × 6. Το tablet κρατά τις 12 στήλες και προσθέτει γραμμές, οπότε η σελίδα χωράει περισσότερα widget. Τα widget κάτω από τις 6 πρώτες γραμμές μένουν στο tablet· το τηλέφωνο δείχνει τις 6 πρώτες.',
      's.lhm.checking': "Έλεγχος πηγής αισθητήρων…",
      's.lhm.connected': "Η πηγή αισθητήρων συνδέθηκε",
      's.lhm.unavailable': "Η πηγή αισθητήρων δεν είναι διαθέσιμη",
      's.lhm.setup': "Για τη θερμοκρασία και ισχύ CPU και πρόσθετες μετρήσεις GPU στα Windows, ενεργοποιήστε Options › Remote Web Server › Run στη θύρα 8085.",
      's.pages.screenHidden': '{n} widget βρίσκονται σε γραμμές που δεν δείχνει αυτή η οθόνη.',
      's.display.tabletRows': 'Περισσότερες γραμμές στο tablet',
      's.display.tabletRowsHint': 'Ένα tablet σε οριζόντιο προσανατολισμό κρατά τις 12 στήλες και παίρνει περισσότερες γραμμές (περίπου 8 έως 10, ανάλογα με την οθόνη), οπότε μια σελίδα χωράει περισσότερα widget· όρθιο, βάζει 12 το ένα δίπλα στο άλλο. Τα widget κάτω από τις 6 πρώτες γραμμές φαίνονται μόνο στο tablet: το τηλέφωνο τα παραλείπει χωρίς ένδειξη. Ενημέρωσε πρώτα την εφαρμογή PhoneBox στο tablet, γιατί μια παλιότερη έκδοση στριμώχνει αυτά τα widget σε επιπλέον γραμμές.',
      's.pages.screenRowsVary': 'Ο πραγματικός αριθμός γραμμών εξαρτάται από την οθόνη του tablet, για παράδειγμα 7 σε 1280 × 720 ή 9 σε 1200 × 800.',
      's.shortcuts.lead': 'Τα πλήκτρα που εμφανίζουν τα widget Πλέγμα συντομεύσεων και Μεγάλο κουμπί. Κάνε κλικ σε ένα πλήκτρο για να το επεξεργαστείς και σύρε για να αλλάξεις τη σειρά. Το τηλέφωνο στέλνει μόνο το id του πλήκτρου· οι εντολές δεν φεύγουν ποτέ από αυτόν τον υπολογιστή.',
      's.rules.lead': 'Κάνε τον πίνακα να αντιδρά σε ό,τι συμβαίνει σε αυτόν τον υπολογιστή: να δείχνει τη σελίδα AI όταν σε χρειάζεται το Claude, τη σελίδα μουσικής όταν παίζει κάτι, μια πινακίδα «On air» στις κλήσεις. Ένας κανόνας ενεργοποιείται όταν αρχίζει η συνθήκη του· με την επιλογή «Μόνο όσο διαρκεί», όταν η συνθήκη τελειώσει το τηλέφωνο επιστρέφει εκεί που ήταν (και η τιμή που στάλθηκε αφαιρείται).',
