      's.cal.hint': 'Για το widget <b>Ατζέντα</b> και τους κανόνες ημερολογίου. Επικόλλησε μια διεύθυνση iCalendar (ICS): Google Calendar › Ρυθμίσεις › το ημερολόγιό σου › <i>Μυστική διεύθυνση σε μορφή iCal</i>· Outlook › Ρυθμίσεις › Ημερολόγιο › Κοινόχρηστα ημερολόγια › <i>Δημοσίευση ημερολογίου</i> (σύνδεσμος ICS)· iCloud › κοινοποίηση ως δημόσιο ημερολόγιο (δουλεύει και το <code>webcal://</code>). Οι διευθύνσεις μένουν σε αυτόν τον υπολογιστή.',
      's.ha.tokenHint': 'Για το widget <b>Home Assistant</b>. Δημιούργησε ένα token στο Home Assistant › το προφίλ σου › Ασφάλεια › <i>Διακριτικά πρόσβασης μακράς διαρκείας</i>. Το token μένει σε αυτόν τον υπολογιστή· το τηλέφωνο βλέπει μόνο τις οντότητες που περιλαμβάνουν τα widget του. (Το Home Assistant μπορεί επίσης να στέλνει τιμές και ειδοποιήσεις στον πίνακα, δες Webhooks.)',
      's.obs.enable': 'Σύνδεση με το OBS (για το widget <b>OBS</b>, το widget On air και τους κανόνες)',
      's.obs.hint': 'Στο OBS: Εργαλεία › Ρυθμίσεις διακομιστή WebSocket › <i>Ενεργοποίηση διακομιστή WebSocket</i>· αντίγραψε τον κωδικό από το <i>Εμφάνιση πληροφοριών σύνδεσης</i>.',
      's.battery.leadTail': 'στην πηγή του: από ένα <b>έξυπνο φις στο Home Assistant</b> (με το τηλέφωνο στον δικό του φορτιστή) ή με δύο <b>συντομεύσεις</b>, για παράδειγμα <code>uhubctl</code> για USB hub με θύρες που ανοιγοκλείνουν. Χωρίς ρεύμα USB ο πίνακας συνεχίζει να λειτουργεί μέσω Wi-Fi.',
      's.claude.hint': 'Όταν το Claude Code ζητά άδεια (για να εκτελέσει μια εντολή, να επεξεργαστεί ένα αρχείο…), το τηλέφωνο εμφανίζει το αίτημα με <b>Αποδοχή</b> και <b>Απόρριψη</b>. Αν το τηλέφωνο δεν είναι συνδεδεμένο ή κανείς δεν απαντήσει εγκαίρως, το Claude Code ρωτά στο τερματικό όπως πάντα. Χρειάζεται ένα μικρό hook στο <code>~/.claude/settings.json</code>· το PhoneBox το προσθέτει για σένα (κρατιέται αντίγραφο ασφαλείας δίπλα στο αρχείο).',
      's.wifi.lead': 'Κάνε σύζευξη ενός τηλεφώνου συνδέοντάς το μία φορά με USB, αφού ενεργοποιήσεις αυτή τη ρύθμιση (και κάνεις επανεκκίνηση), ή χωρίς καλώδιο: το κουμπί <b>Σύζευξη τηλεφώνου μέσω Wi-Fi</b> εμφανίζει έναν κωδικό QR για σάρωση με την κάμερα του τηλεφώνου. Στη συνέχεια το τηλέφωνο επικοινωνεί μέσω HTTPS με αυτό το PC, εμπιστεύεται μόνο το πιστοποιητικό του και πρέπει να δείξει ένα μυστικό κλειδί. Το τηλέφωνο και αυτό το PC πρέπει να είναι στο ίδιο δίκτυο &mdash; ή και τα δύο στο <a href="https://tailscale.com" target="_blank" rel="noopener">Tailscale</a>, που δουλεύει και από άλλο μέρος ή μεταξύ διαφορετικών δικτύων Wi-Fi. Το Τείχος προστασίας των Windows ρωτά μία φορά &mdash; επίτρεψέ το (τσέκαρε και τον τύπο δικτύου που χρησιμοποιεί το Tailscale).',
      's.upd.checksBefore': 'Ελέγχει το',
      's.upd.checksAfter': 'στο GitHub κάθε 6 ώρες για ενημερώσεις. Η εφαρμογή τηλεφώνου εγκαθίσταται μέσω USB χωρίς να ζητηθεί επιβεβαίωση στο τηλέφωνο· ο agent αντικαθιστά μόνος του τα αρχεία του και κάνει επανεκκίνηση.',
