      's.battery.leadHead': 'Ένα τηλέφωνο που είναι συνεχώς στο ρεύμα φθείρει την μπαταρία του. Το PhoneBox μπορεί να την κρατά ανάμεσα σε δύο',
      's.battery.leadMid': 'επίπεδα, ανοίγοντας και κλείνοντας το ρεύμα του τηλεφώνου. Τα τηλέφωνα δεν μπορούν να σταματήσουν μόνα τους τη φόρτιση χωρίς root, οπότε το ρεύμα ανοιγοκλείνει',
      's.wh.payloadHintFull': 'Τα payloads JSON μπορούν να περιέχουν <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / warn / error), <code>progress</code> (0&ndash;1 ή 0&ndash;100), <code>items</code> (λίστα) και <code>ttl</code> (δευτερόλεπτα). Δουλεύει και απλό κείμενο ή αριθμός. Οι ειδοποιήσεις δέχονται <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (ανάβει τη νυχτερινή οθόνη) και <code>page</code> (αλλάζει σε αυτή τη σελίδα).',
