      's.cursor.hint': 'Εμφάνιση των πρόσφατων συνομιλιών του Cursor agent στο widget Συνεδρίες AI (απενεργοποιημένο από προεπιλογή). Κρατιέται μόνο ο ρόλος του τελευταίου μηνύματος· το κείμενο των συνομιλιών δεν εμφανίζεται, δεν αποθηκεύεται και δεν στέλνεται ποτέ. Τα ονόματα των έργων προέρχονται από το όνομα του φακέλου στο workspaceStorage του Cursor.',
