      's.antigravity.hint': 'Εμφάνιση των πρόσφατων συνομιλιών του Antigravity στο widget Συνεδρίες AI (απενεργοποιημένο από προεπιλογή). Κρατιούνται μόνο τα μεταδεδομένα βημάτων και οι μετρητές token· οι εντολές, οι απαντήσεις και τα ορίσματα εργαλείων δεν εμφανίζονται, δεν αποθηκεύονται και δεν στέλνονται ποτέ.',
