      's.opencode.hint': 'Τα αιτήματα άδειας του OpenCode και οι ερωτήσεις των agents φτάνουν στο τηλέφωνο ενώ τρέχει η υπηρεσία παρασκηνίου. Μένει ανενεργό μέχρι να το ενεργοποιήσετε εδώ. Το «Να επιτρέπεται πάντα» αποθηκεύει το ζητούμενο μοτίβο για το project, γι αυτό το κουμπί ενεργοποιείται μετά από λίγα δευτερόλεπτα.',
