      's.opencode.watchWsl': 'Παρακολούθηση και του OpenCode μέσα σε WSL (οι απενεργοποιημένες διανομές δεν εκκινούνται γι αυτό)',
      's.approvals.cursor': 'Cursor',
      's.cursor.askOnPhone': 'Ερώτηση στο τηλέφωνο για το Cursor',
      's.claude.timeoutReinstall': 'Κάθε hook κρατά τα δευτερόλεπτα με τα οποία εγκαταστάθηκε: αφού τα αλλάξεις, αφαίρεσε το hook και εγκατάστησέ το ξανά.',
      's.cursor.approvalsHint': 'Το hook του Cursor εκτελείται πριν από κάθε εντολή κελύφους και κάθε κλήση εργαλείου MCP του πράκτορά του, ακόμη και όσες θα εκτελούσε μόνος του. Όσο είναι συνδεδεμένο ένα τηλέφωνο, η καθεμία περιμένει εκεί Να επιτρέπεται ή Άρνηση· χωρίς τηλέφωνο ή χωρίς απάντηση, το Cursor συνεχίζει κανονικά. Με ενεργό το «Παρακολούθηση και του Cursor στο WSL», το hook εγκαθίσταται και στις διανομές που εκτελούνται (τα έργα που ανοίγουν με Remote - WSL εκτελούν εκεί τα hooks τους).',
