      's.claude.extraDirs': 'Άλλοι λογαριασμοί Claude Code για το όριο, τις συνεδρίες και τα αιτήματα άδειας: μια ετικέτα και ο φάκελος που χρησιμοποιείται ως CLAUDE_CONFIG_DIR. Στο τηλέφωνο φτάνει μόνο η ετικέτα. Η ετικέτα είναι μέρος του id της κάρτας: η μετονομασία αλλάζει το id, οπότε επιλέξτε ξανά τον λογαριασμό στα widget που τον χρησιμοποιούν.',
