      's.discord.hint': 'Tạo một ứng dụng tại discord.com/developers/applications, thêm địa chỉ chuyển hướng http://127.0.0.1 trong mục OAuth2, rồi sao chép client ID và secret của nó vào đây. Discord sẽ yêu cầu bạn phê duyệt PhoneBox một lần. Nếu nó từ chối đăng nhập, hãy thêm tài khoản của bạn vào mục App Testers của ứng dụng. Từng bước: docs/DISCORD.md.',
