      's.discord.allowControlHint': 'Dành cho các thao tác /api/discord của agent: tắt mic, tắt âm thanh, chế độ đầu vào, rời và tham gia. Tắt: chỉ hoạt động khi có widget Discord bật quyền điều khiển trên một trang đang bật. Bật: hoạt động không cần widget. Trong cả hai trường hợp, mọi thứ gọi được agent đều dùng được, không chỉ widget: điện thoại đã ghép nối (USB hoặc Wi-Fi) và các chương trình trên máy tính này.',
      's.discord.screenShare': 'Bắt đầu và dừng chia sẻ màn hình Discord từ điện thoại',
      's.discord.screenShareHint': 'Xin Discord quyền bắt đầu chia sẻ màn hình, nên Discord sẽ yêu cầu bạn chấp thuận PhoneBox thêm một lần. Khi màn hình chia sẻ đang mở trên điện thoại, PhoneBox liệt kê các ứng dụng có cửa sổ trên máy tính này (chỉ tên). Discord quyết định những gì nó chia sẻ trực tiếp được; với thứ khác hãy dùng bộ chọn của nó trên máy tính. Cũng cần một widget Discord đã bật điều khiển.',
