      's.pages.screen.wide': 'Máy tính bảng rộng',
      's.pages.screenHint': 'Một trang trên điện thoại là 12 × 6. Máy tính bảng giữ 12 cột và thêm hàng, nên trang chứa được nhiều widget hơn. Widget nằm dưới 6 hàng đầu chỉ hiện trên máy tính bảng; điện thoại hiện 6 hàng đầu.',
      's.lhm.checking': "Đang kiểm tra nguồn cảm biến…",
