      's.lhm.setup': "Để xem nhiệt độ và công suất CPU cùng các chỉ số GPU bổ sung trên Windows, hãy bật Options › Remote Web Server › Run ở cổng 8085.",
      's.pages.screenHidden': '{n} widget nằm trên các hàng mà màn hình này không hiển thị.',
      's.display.tabletRows': 'Thêm hàng trên máy tính bảng',
      's.display.tabletRowsHint': 'Máy tính bảng nằm ngang giữ 12 cột và có thêm hàng (khoảng 8 đến 10, tùy màn hình), nên mỗi trang chứa được nhiều widget hơn; khi dựng đứng, nó xếp 12 widget cạnh nhau. Widget nằm dưới 6 hàng đầu chỉ hiện trên máy tính bảng: điện thoại bỏ qua chúng mà không báo. Hãy cập nhật ứng dụng PhoneBox trên máy tính bảng trước, vì bản cũ sẽ dồn các widget đó vào các hàng thừa.',
      's.pages.screenRowsVary': 'Số hàng thực tế tùy vào màn hình máy tính bảng, ví dụ 7 hàng ở 1280 × 720 hoặc 9 hàng ở 1200 × 800.',
      's.shortcuts.lead': 'Các phím được hiển thị bởi widget Lưới phím tắt và Nút lớn. Nhấp vào một phím để chỉnh sửa, kéo để sắp xếp lại. Điện thoại chỉ gửi id của phím; các lệnh không bao giờ rời khỏi máy tính này.',
      's.rules.lead': 'Để bảng điều khiển phản ứng với những gì xảy ra trên máy tính này: hiện trang AI khi Claude cần bạn, trang nhạc khi có gì đó đang phát, biển báo "đang phát sóng" trong các cuộc gọi. Một quy tắc kích hoạt khi điều kiện của nó bắt đầu; với tùy chọn chỉ trong lúc điều kiện kéo dài, điện thoại sẽ quay lại nơi trước đó (và giá trị đã đẩy sẽ bị xóa) khi điều kiện kết thúc.',
